import blueprints
# ============================================================================
# SECCIÓN 1: FUNCIONES HELPER
# ============================================================================
# Las funciones helper son plantillas reutilizables que construyen estructuras
# de datos. Reciben parámetros (incluyendo expresiones CEL) y devuelven objetos.
_buildPostgresContainer = lambda image: str, secretName: str -> any {
{
name = "postgres"
image = image
ports = [{
containerPort = 5432
}]
env = [
{
name = "POSTGRES_DB"
value = "keycloak"
}
{
name = "POSTGRES_USER"
value = "keycloak"
}
{
name = "POSTGRES_PASSWORD"
valueFrom = {
secretKeyRef = {
name = secretName
key = "password"
}
}
}
]
}
}
_buildServiceTemplate = lambda name: str, selector: {str:str}, port: int -> any {
{
apiVersion = "v1"
kind = "Service"
metadata = {
name = name # Puede incluir expresiones CEL
namespace = "default"
}
spec = {
selector = selector
ports = [{
port = port
targetPort = port
protocol = "TCP"
}]
type = "ClusterIP"
}
}
}
_includeWhenLocal = lambda isLocal: bool -> [str] {
[r"${schema.spec.localTest}"] if isLocal else [r"${!schema.spec.localTest}"]
}
_tagsTemplate = lambda name: str, projectName: str -> [any] {
[
{
key = "Name"
value = name
}
{
key = "Project"
value = projectName
}
]
}
blueprints.ResourcegraphdefinitionBlueprint {
_metadataName = "keycloak-stack"
_schema = {
apiVersion = "v1alpha1"
kind = "KeycloakStack"
group = "kro.run"
# Campos del spec (lo que el usuario proporciona en el claim)
spec.projectName = "string | default=demo"
spec.environment = "string | default=dev" # dev = sin certificado (HTTP), prod = con certificado (HTTPS)
spec.keycloakMode = r"""string | default="start-dev" """ # start-dev o start (producción)
spec.keycloakReplicas = "integer | default=1"
spec.keycloakImage = r"""string | default="quay.io/keycloak/keycloak:latest" """
spec.keycloakAdminUser = "string | default=admin"
spec.keycloakHostname = "string | required=true"
spec.certificateSecretName = "string"
spec.postgresImage = r"""string | default="postgres:15" """
spec.postgresPassword = "string | required=true"
# Configuración de producción
spec.kcProxy = r"""string | default="" """ # forwarded, xforwarded, o vacío para deshabilitar (desarrollo local)
spec.kcHttpEnabled = r"""boolean | default=true""" # Permitir HTTP interno cuando proxy=edge
spec.resourceRequestsCpu = r"""string | default="500m" """
spec.resourceRequestsMemory = r"""string | default="1Gi" """
spec.resourceLimitsCpu = r"""string | default="2000m" """
spec.resourceLimitsMemory = r"""string | default="2Gi" """
###### RDS.
spec.localTest = r"""boolean | required=true"""
spec.rdsInstanceClass = r"""string | default="db.t3.micro" """
spec.rdsAllocatedStorage = r"""integer | default=20"""
spec.rdsEngineVersion = r"""string | default="15" """
spec.rdsDBName = r"""string | default="keycloak" """
spec.rdsUsername = r"""string | default="keycloak" """
# Opciones para manejar el password de RDS:
# Opción 1: Password directo
spec.rdsPassword = "string"
# Opción 2: Referenciar un Secret existente
spec.rdsPasswordSecretName = "string"
spec.rdsPasswordSecretKey = r"""string | default="password" """
# Opción 3: AWS Secrets Manager
spec.rdsManageMasterUserPassword = r"""boolean | default=false"""
spec.rdsSubnetGroupName = "string"
spec.rdsSubnetIDs = "[]string"
spec.rdsVPCID = "string"
spec.rdsSecurityGroupIDs = "[]string"
spec.rdsAllowedCIDRs = "[]string"
}
_resources = [
{
id = "postgresSecret"
includeWhen = _includeWhenLocal(True)
template = {
apiVersion = "v1"
kind = "Secret"
metadata.name = r"postgres-secrets-${schema.spec.projectName}"
metadata.namespace = "default"
stringData = {
username = "keycloak"
password = r"${schema.spec.postgresPassword}"
endpoint = "postgres-service"
port = "5432"
}
}
}
{
id = "postgresDeployment"
includeWhen = _includeWhenLocal(True)
template = {
apiVersion = "apps/v1"
kind = "Deployment"
metadata = {
name = r"postgres-${schema.spec.projectName}"
namespace = "default"
}
spec = {
replicas = 1
selector = {
matchLabels = {
app = "postgres"
project = r"${schema.spec.projectName}"
}
}
template = {
metadata = {
labels = {
app = "postgres"
project = r"${schema.spec.projectName}"
}
}
spec = {
containers = [
_buildPostgresContainer(
r"${schema.spec.postgresImage}",
r"${postgresSecret.metadata.name}"
)
]
}
}
}
}
}
{
id = "postgresService"
includeWhen = _includeWhenLocal(True)
template = _buildServiceTemplate(
"postgres-service",
{
