# EXPRESIÓN CEL en el selector
project = r"${schema.spec.projectName}"
},
5432
)
}
{
id = "rdsSubnetGroup"
includeWhen = [
r"${!schema.spec.localTest}",
r"${!has(schema.spec.rdsSubnetGroupName) || schema.spec.rdsSubnetGroupName == ''}",
